/bin/zsh -c "node --input-type=module - /tmp/rzm-expiry.sC0vuw/connection.json <<'EOF'
import { readFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';

const connection = JSON.parse(await readFile(process.argv[2], 'utf8'));
const { createClient } = await import(pathToFileURL(connection.modulePath).href);
const client = createClient({
  executablePath: connection.executablePath,
  vaultPath: connection.vaultPath,
});
try {
  const context = await client.fileContext({
    files: ['src/expiry.py', 'src/CONTEXT.md', 'docs/reference/expiry-policy.md', 'tests/test_expiry.py'],
    intent: 'Repair the expiration boundary behavior while preserving the public API and persisted UTC representation.',
    budgetChars: 20000,
  });
  const source = await client.files({
    inputs: ['src/expiry.py', 'docs/reference/expiry-policy.md', 'tests/test_expiry.py'],
    includeContent: true,
    budgetChars: 20000,
  });
  const symbol = await client.codeSymbolContext({
    symbol: 'is_valid',
    path: 'src/expiry.py',
    includeTests: true,
    budgetChars: 16000,
  });
  const references = await client.codeReferences({
    symbol: 'is_valid',
    path: 'src/expiry.py',
    includeDefinitions: true,
    includeCallers: true,
    includeCallees: true,
    limit: 50,
    budgetChars: 12000,
  });
  console.log(JSON.stringify({ context, source, symbol, references }, null, 2));
} finally {
  await client.close();
}
EOF"
